// Complex subsystems
public class CPU { public void Start() { /* ... */ } }
public class Memory { public void Load() { /* ... */ } }
public class HardDrive { public void Read() { /* ... */ } }

// Facade
public class ComputerFacade
{
    private readonly CPU _cpu = new CPU();
    private readonly Memory _memory = new Memory();
    private readonly HardDrive _hardDrive = new HardDrive();

    public void Start()
    {
        _cpu.Start();
        _memory.Load();
        _hardDrive.Read();
    }
}

// Client uses simple interface
var computer = new ComputerFacade();
computer.Start();
